        <div id="send-button" style="width: 36px; height: 36px; margin-left: 10px; display: flex; justify-content: center; align-items: center; cursor: pointer;">
            <svg style="width: 24px; height: 24px; fill: #555;" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"></path></svg>
        </div>
    </div>
</div>

<script>
    // JavaScript functionality is unchanged
    document.addEventListener('DOMContentLoaded', function() {
        const chatInput = document.getElementById('chat-input');
        const sendButton = document.getElementById('send-button');

        function sendMessage() {
            const message = chatInput.value.trim();
            if (message) {
                // Assuming triggerSlash is defined elsewhere
                if (typeof triggerSlash === 'function') {
                    const command = `/send 回复消息：${message} |/trigger`;
                    triggerSlash(command);
                    chatInput.value = '';
                } else {
                    console.error('triggerSlash function is not defined.');
                }
            }
        }

        if (sendButton) {
            sendButton.addEventListener('click', sendMessage);
        }

        if (chatInput) {
            chatInput.addEventListener('keydown', function(event) {
                if (event.key === 'Enter') {
                    event.preventDefault();
                    sendMessage();
                }
            });
        }
    });
</script>

</body>
</html>
